import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../data/action_context'
import { CUSTOM_PROMPT_ACTION_ID } from '../../data/action_types'
import type { AgentConversation } from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import { useActions } from '../hooks/use_actions'
import { useProjectState } from '../hooks/use_project_state'
import { useProjectActionWorktree } from '../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onClose: () => void
    onConversationViewed?: (conversation: AgentConversation) => void
    open?: boolean
    unseenResultActionIds?: string[]
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [showSaveControls, setShowSaveControls] = useState(false)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
        setShowSaveControls(false)
    }

    const handleAddAction = () => {
        try {
            const customPrompt = actions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
            if (!customPrompt) throw new Error('Missing custom prompt action')

            setSelectedActionId(customPrompt.id)
            setShowSaveControls((current) => !current)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Custom action editor could not be opened' })
        }
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onAddAction={handleAddAction}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            showSaveControls={showSaveControls}
            titleId={titleId}
        />
    )
}

import { Box, Stack, Typography } from '@mui/material'
import { useEffect, useLayoutEffect, useRef, type UIEvent } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import type { AgentConversation, AgentConversationEvent } from '../../data/data_types'
import { useAppTheme } from '../../theme/use_app_theme'
import type { PopupRunStatus } from './action_popup_defaults'
import { ActionConversationLink } from './action_conversation_link'
import { actionConversationUrlTransform } from './action_conversation_url_transform'
import { actionStatusLabel } from './action_status'
import { ConversationTimer } from './conversation_timer'
import { AgentToolEvent } from './agent_tool_event'
import { CommandExecutionEvent } from './command_execution_event'
import { ReasoningEvent } from './reasoning_event'
import { eventIdentity } from './event_display'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96
const MARKDOWN_COMPONENTS = { a: ActionConversationLink }

interface ActionConversationChatProps {
    conversation: AgentConversation | null
    onConversationViewed?: (conversation: AgentConversation) => void
    status: PopupRunStatus
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

function isCodexConversation(conversation: AgentConversation) {
    return conversation.providerSessions.some(({ agent }) => agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'message' && entry.agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'event' && !!entry.providerItemId)
}

function visibleConversationEntries(conversation: AgentConversation | null) {
    if (!conversation) return []
    const showEvents = isCodexConversation(conversation)

    return conversation.entries.filter((entry) => entry.kind === 'message'
        || (showEvents && (entry.type !== 'reasoning' || entry.status !== 'completed')))
}

function renderEvent(event: AgentConversationEvent) {
    if (event.type === 'reasoning') return <ReasoningEvent event={event} />
    if (event.type === 'commandExecution') return <CommandExecutionEvent event={event} />

    return <AgentToolEvent event={event} />
}

/** Ordered user/assistant transcript shown above the popup prompt. */
export function ActionConversationChat({ conversation, onConversationViewed, status }: ActionConversationChatProps) {
    const { markdownContentSx } = useAppTheme()
    const entries = visibleConversationEntries(conversation)
    const viewportRef = useRef<HTMLDivElement>(null)
    const conversationPathRef = useRef<string | null | undefined>(undefined)
    const stuckToEndRef = useRef(true)

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    useEffect(() => {
        if (!conversation?.completedAt || conversation.status === 'running' || conversation.status === 'waitingForInput') return

        onConversationViewed?.(conversation)
    }, [conversation, onConversationViewed])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const conversationPath = conversation?.path ?? null
        const conversationChanged = conversationPathRef.current !== conversationPath
        conversationPathRef.current = conversationPath
        if (conversationChanged) stuckToEndRef.current = true
        if (!stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    })

    return (
        <Stack
            aria-label="Conversation chat"
            onScroll={handleScroll}
            ref={viewportRef}
            spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}
        >
            {entries.map((entry) => entry.kind === 'message' ? (
                <Box
                    key={entry.id}
                    sx={{
                        alignSelf: entry.role === 'user' ? 'flex-end' : 'flex-start',
                        bgcolor: entry.role === 'user' ? 'custom.primaryBg' : 'custom.track',
                        borderRadius: 1,
                        flexShrink: 0,
                        maxWidth: '88%',
                        minWidth: 0,
                        overflowWrap: 'anywhere',
                        px: 1.25,
                        py: 1,
                        ...markdownContentSx,
                    }}
                >
                    <Box className="mdxeditor-content">
                        <ReactMarkdown
                            components={MARKDOWN_COMPONENTS}
                            remarkPlugins={[remarkGfm]}
                            urlTransform={actionConversationUrlTransform}
                        >
                            {entry.content}
                        </ReactMarkdown>
                    </Box>
                </Box>
            ) : (
                <Box key={eventIdentity(entry)} sx={{ minWidth: 0 }}>
                    {renderEvent(entry)}
                </Box>
            ))}
            {status !== 'idle' ? (
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', flexShrink: 0 }}>
                    <Typography color={status === 'failed' ? 'error.main' : 'text.secondary'} role="status" variant="caption">
                        {actionStatusLabel(status)}
                    </Typography>
                    {conversation ? (
                        <ConversationTimer completedAt={conversation.completedAt} startedAt={conversation.startedAt} status={status} />
                    ) : null}
                </Stack>
            ) : null}
        </Stack>
    )
}

import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { AgentConversation } from '../../data/data_types'
import { useActionRunSelector } from '../hooks/use_action_runs'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    onConversationViewed?: (conversation: AgentConversation) => void
    store: ActionConversationStore
}

/** Subscribes only chat boundary to selected and canonical live conversation changes. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, onConversationViewed, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus

    return <ActionConversationChat conversation={conversation} onConversationViewed={onConversationViewed} status={status} />
}

import { useEffect, useSyncExternalStore, type ChangeEvent } from 'react'
import type { ActionContext } from '../../data/action_context'
import { useActionRun } from '../hooks/use_action_runs'
import { ActionConversationPicker } from './action_conversation_picker'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationPickerOwnerProps {
    actionId: string
    context: ActionContext
    store: ActionConversationStore
}

/** Loads and selects conversation history at picker boundary. */
export function ActionConversationPickerOwner(props: ActionConversationPickerOwnerProps) {
    const { actionId, context, store } = props
    const run = useActionRun(actionId, context)
    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    const liveConversation = run?.conversation ?? null

    useEffect(() => {
        void store.load()
    }, [store])

    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        void store.select(event.target.value)
    }

    return (
        <ActionConversationPicker
            conversations={store.conversationOptions(liveConversation)}
            disabled={sessionActive}
            loading={snapshot.loading}
            onChange={handleChange}
            selectedPath={liveConversation?.path ?? snapshot.selectedConversation?.path ?? ''}
        />
    )
}

import type { AgentConversation } from '../../data/data_types'

export function formatConversationDateTime(startedAt: string) {
    const date = new Date(startedAt)
    if (Number.isNaN(date.getTime())) return startedAt

    return date.toLocaleString(undefined, { dateStyle: 'short', timeStyle: 'short' })
}

export function conversationPickerLabel(conversation: AgentConversation) {
    const dateTime = formatConversationDateTime(conversation.startedAt)

    return conversation.hasExplicitTitle ? `${conversation.title} â€” ${dateTime}` : dateTime
}

